            if (vert) e.line([[cp, L.a0 - ex], [cp, L.a1 + ex + d]], lc, lw, (i.alpha ?? 1) * Math.min(1, q), false);
            else e.line([[L.a0 - ex, cp], [L.a1 + ex + d, cp]], lc, lw, (i.alpha ?? 1) * Math.min(1, q), false);
